CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,hash TEXT NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records (owner TEXT NOT NULL,entity TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(owner,entity,id));
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY,owner TEXT NOT NULL,device TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL DEFAULT 'Queued',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions (hash TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_jobs (id TEXT PRIMARY KEY,owner TEXT NOT NULL,device TEXT NOT NULL,messages TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',response TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT '等待电脑接入',error TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL DEFAULT '',model TEXT NOT NULL DEFAULT '',cancelled INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ai_jobs_owner_status ON ai_jobs(owner,status,created);
